19	export type FileName =
20	  | typeof GLOBAL_CONFIG_YAML_FILENAME
21	  | typeof WORKSPACE_MANIFEST_FILENAME
22	
23	const DEFAULT_FILENAME: FileName = WORKSPACE_MANIFEST_FILENAME
