25	async function writeManifestFile (dir: string, fileName: FileName, manifest: yaml.Document): Promise<void> {
26	  const manifestStr = manifest.toString({
27	    lineWidth: 0, // This is setting line width to never wrap
28	    singleQuote: true, // Prefer single quotes over double quotes
29	  })
30	  await fs.promises.mkdir(dir, { recursive: true })
31	  await writeFileAtomic(path.join(dir, fileName), manifestStr)
32	}
33	
34	async function readManifestRaw (file: string): Promise<string | undefined> {
35	  try {
36	    return (await fs.promises.readFile(file)).toString()
37	  } catch (err) {
38	    if (util.types.isNativeError(err) && 'code' in err && err.code === 'ENOENT') {
39	      return undefined
40	    }
41	    throw err
42	  }
43	}
