45	export async function updateWorkspaceManifest (dir: string, opts: {
46	  updatedFields?: Partial<WorkspaceManifest>
47	  updatedCatalogs?: Catalogs
48	  updatedOverrides?: Record<string, string>
49	  addedMinimumReleaseAgeExcludes?: string[]
50	  fileName?: FileName
51	  cleanupUnusedCatalogs?: boolean
52	  allProjects?: Project[]
53	}): Promise<void> {
54	  const fileName = opts.fileName ?? DEFAULT_FILENAME
55	
56	  const workspaceManifestStr = await readManifestRaw(path.join(dir, fileName))
57	
58	  const document = workspaceManifestStr != null
59	    ? yaml.parseDocument(workspaceManifestStr)
60	    : new yaml.Document()
61	
62	  let manifest = document.toJSON()
63	  validateWorkspaceManifest(manifest)
64	  manifest ??= {}
65	
66	  let shouldBeUpdated = opts.updatedCatalogs != null && addCatalogs(manifest, opts.updatedCatalogs)
67	  if (opts.cleanupUnusedCatalogs) {
68	    shouldBeUpdated = removePackagesFromWorkspaceCatalog(manifest, opts.allProjects ?? []) || shouldBeUpdated
69	  }
70	
71	  const updatedFields = { ...opts.updatedFields }
72	
73	  for (const [key, value] of Object.entries(updatedFields)) {
74	    if (!equals(manifest[key as keyof WorkspaceManifest], value)) {
75	      shouldBeUpdated = true
76	      if (value == null) {
77	        delete manifest[key as keyof WorkspaceManifest]
78	      } else {
79	        manifest[key as keyof WorkspaceManifest] = value
80	      }
81	    }
82	  }
83	  if (opts.updatedOverrides) {
84	    manifest.overrides ??= {}
85	    for (const [key, value] of Object.entries(opts.updatedOverrides)) {
86	      if (!equals(manifest.overrides[key], value)) {
87	        shouldBeUpdated = true
88	        manifest.overrides[key] = value
89	      }
90	    }
91	  }
92	  if (opts.addedMinimumReleaseAgeExcludes?.length) {
93	    const existing: string[] = manifest.minimumReleaseAgeExclude ?? []
94	    const existingSet = new Set(existing)
95	    const newEntries = [...new Set(opts.addedMinimumReleaseAgeExcludes)].filter((entry) => !existingSet.has(entry))
96	    if (newEntries.length > 0) {
97	      shouldBeUpdated = true
98	      manifest.minimumReleaseAgeExclude = [...existing, ...newEntries]
99	    }
100	  }
101	  if (!shouldBeUpdated) {
102	    return
103	  }
104	  if (Object.keys(manifest).length === 0) {
105	    await fs.promises.rm(path.join(dir, fileName))
106	    return
107	  }
108	
109	  manifest = sortKeysByPriority({
110	    priority: { packages: 0 },
111	    deep: true,
112	  }, manifest)
113	
114	  patchDocument(document, manifest)
115	
116	  await writeManifestFile(dir, fileName, document)
117	}
