125	function addCatalogs (manifest: Partial<WorkspaceManifest>, newCatalogs: Catalogs): boolean {
126	  let shouldBeUpdated = false
127	
128	  for (const catalogName in newCatalogs) {
129	    let targetCatalog: Record<string, string> | undefined = catalogName === 'default'
130	      ? manifest.catalog ?? manifest.catalogs?.default
131	      : manifest.catalogs?.[catalogName]
132	    const targetCatalogWasNil = targetCatalog == null
133	
134	    for (const [dependencyName, specifier] of Object.entries(newCatalogs[catalogName] ?? {})) {
135	      if (specifier == null) {
136	        continue
137	      }
138	
139	      targetCatalog ??= {}
140	      if (targetCatalog[dependencyName] !== specifier) {
141	        targetCatalog[dependencyName] = specifier
142	        shouldBeUpdated = true
143	      }
144	    }
145	
146	    if (targetCatalog == null) continue
147	
148	    if (targetCatalogWasNil) {
149	      if (catalogName === 'default') {
150	        manifest.catalog = targetCatalog
151	      } else {
152	        manifest.catalogs ??= {}
153	        manifest.catalogs[catalogName] = targetCatalog
154	      }
155	    }
156	  }
157	
158	  return shouldBeUpdated
159	}
