3	export interface PatchDocumentOptions {
4	  /**
5	   * Updating aliases is inherently ambiguous since they're not a concept in
6	   * JSON. The default is to unwrap and remove aliases since that's the most
7	   * correct behavior.
8	   *
9	   * Aliases can be configured to "follow", which updates the anchor node.
10	   * However, this can result in surprising behavior when values in the target
11	   * JSON between the anchor and the alias don't match.
12	   *
13	   * @default 'unwrap'
14	   */
15	  readonly aliases?: 'unwrap' | 'follow'
16	}
17	
18	interface PatchContext extends PatchDocumentOptions {
19	  readonly document: yaml.Document
20	  readonly aliases: 'unwrap' | 'follow'
21	}
22	
23	/**
24	 * Recursively update a YAML document (in-place) to match the contents of a
25	 * target value.
26	 *
27	 * Comments are preserved on a best-effort basis. There are several cases where
28	 * ambiguity arises. See this package's README.md for details.
29	 */
30	export function patchDocument (document: yaml.Document, target: unknown, options?: PatchDocumentOptions): void {
31	  // Documents with errors can't be stringified and have unpredictable ASTs.
32	  if (document.errors.length > 0) {
33	    throw new Error('Document with errors cannot be patched')
34	  }
35	
36	  document.contents = patchNode(document.contents, target, {
37	    document,
38	    aliases: options?.aliases ?? 'unwrap',
39	  })
40	}
41	
42	function patchNode (node: yaml.Node | null | undefined, target: unknown, ctx: PatchContext): yaml.Node | null {
43	  if (node == null) {
44	    return ctx.document.createNode(target)
45	  }
46	
47	  if (target == null) {
48	    return null
49	  }
50	
51	  if (yaml.isAlias(node)) {
52	    return patchAlias(node, target, ctx)
53	  }
54	
55	  if (yaml.isScalar(node)) {
56	    return patchScalar(node, target, ctx)
57	  }
58	
59	  if (yaml.isMap(node)) {
60	    return patchMap(node, target, ctx)
61	  }
62	
63	  if (yaml.isSeq(node)) {
64	    return patchSeq(node, target, ctx)
65	  }
66	
67	  const _never: never = node
68	  throw new Error('Unrecognized yaml node: ' + String(node))
69	}
70	
71	function patchAlias (alias: yaml.Alias, target: unknown, ctx: PatchContext): yaml.Node | null {
72	  const resolved = alias.resolve(ctx.document)
73	
74	  // This should only happen if the document was corrupted after it was parsed.
75	  // Unresolved aliases should fail at the parsing stage.
76	  if (resolved == null) {
77	    throw new Error('Failed to resolve yaml alias: ' + alias.source)
78	  }
79	
80	  switch (ctx.aliases) {
81	    case 'follow': {
82	    // This can result in surprising behavior since the anchor node will end up
83	    // with the contents of the last encountered alias. The default is to
84	    // "unwrap" for this reason.
85	      patchNode(resolved, target, ctx)
86	      return alias
87	    }
88	
89	    case 'unwrap': {
90	      const copy = resolved.clone() as typeof resolved
91	      copy.anchor = undefined
92	      patchNode(copy, target, ctx)
93	      return copy
94	    }
95	  }
96	}
97	
98	function patchScalar (scalar: yaml.Scalar, target: unknown, ctx: PatchContext): yaml.Node {
99	  if (scalar.value === target) {
100	    return scalar
101	  }
102	
103	  if (typeof target === 'boolean' || typeof target === 'string' || typeof target === 'number') {
104	    scalar.value = target
105	    return scalar
106	  }
107	
108	  return ctx.document.createNode(target)
109	}
110	
111	function patchMap (map: yaml.YAMLMap, target: unknown, ctx: PatchContext): yaml.Node | null {
112	  if (!isRecord(target)) {
113	    return ctx.document.createNode(target)
114	  }
115	
116	  // Intentionally return null on empty maps as well. This recursively clears
117	  // empty maps in the final document.
118	  if (target == null || Object.keys(target).length === 0) {
